import React from "react";

import * as d3 from "d3";

const angleToRad = (angle) => {
  const angleCircle = angle - 90;
  const radLine = (angle * Math.PI) / 180;
  const radCircle = -(angleCircle * Math.PI) / 180;

  return [radLine, radCircle];
};

export default function AngleChart({ angle, width, height }) {
  const [radLine, radCircle] = angleToRad(angle);

  console.log(width, height, angle);

  const centerX = width / 2;
  const centerY = height / 2;

  const lineLength = width / 2;

  // Line 1: pointing to the right (reference line)
  const x1 = lineLength * Math.cos(0);
  const y1 = -lineLength * Math.sin(0);

  // // Line 2: based on the angle
  const x2 = +lineLength * Math.cos(radLine);
  const y2 = -lineLength * Math.sin(radLine);

  const data = d3.arc()({
    innerRadius: 0,
    outerRadius: (width / 2) * 0.9,
    startAngle: Math.PI / 2,
    endAngle: radCircle,
  });

  const { colorLine, colorFill } =
    angle === 90
      ? {
          colorLine: "#d946ef",
          colorFill: "#f5d0fe",
        }
      : angle < 90
      ? {
          colorLine: "#34d399",
          colorFill: "#a7f3d0",
        }
      : {
          colorLine: "#fb7185",
          colorFill: "#fecdd3",
        };

  return (
    <svg width={width} height={height}>
      <g transform={`translate(${centerX},${centerY})`}>
        <path fill={colorFill} d={data} />
        <line
          x1={0}
          x2={x2}
          y1={0}
          y2={y2}
          stroke={colorLine}
          strokeWidth={2}
        />
        <line x1={0} x2={width} y1={0} y2={0} stroke="black" strokeWidth={2} />
      </g>
    </svg>
  );
}
