import React from "react";

export default function ErrorChart({ estimate, standardError, width, height }) {
  const y = height / 2;

  return (
    <svg width={width} height={height} className="bg-slate-100">
      <line x1={50} x2={350} y1={y} y2={y} stroke="black" />

      <line
        x1={estimate - standardError}
        x2={estimate + standardError}
        y1={y}
        y2={y}
        strokeWidth={3}
        stroke="black"
      />

      <circle
        r={6}
        stroke={"#64748b"}
        strokeWidth={2}
        cx={estimate}
        cy={y}
        fill={"#f1f5f9"}
      />
    </svg>
  );
}
